    static readonly Dictionary<string, Texture2D> texCache = new Dictionary<string, Texture2D>();
    static readonly Dictionary<string, Sprite> spriteCache = new Dictionary<string, Sprite>();

    /// <summary>Çalışma anında üretilen nesnelerin sahne yüklenince silinmesini engeller.</summary>
    public static Sprite Keep(Sprite s) { if (s != null) s.hideFlags = HideFlags.HideAndDontSave; return s; }
    public static Texture2D Keep(Texture2D t) { if (t != null) t.hideFlags = HideFlags.HideAndDontSave; return t; }

    public static bool Has(string name) { return Data.ContainsKey(name); }

    public static Texture2D Tex(string name)
    {
        Texture2D t;
        if (texCache.TryGetValue(name, out t) && t != null) return t;
        string b64;
        if (!Data.TryGetValue(name, out b64)) return null;
        t = new Texture2D(2, 2, TextureFormat.RGBA32, false);
        t.LoadImage(System.Convert.FromBase64String(b64), false);
        t.filterMode = FilterMode.Point;
        t.wrapMode = TextureWrapMode.Clamp;
        t.name = "ART_" + name;
        t.hideFlags = HideFlags.HideAndDontSave;   // sahne yüklenince silinmesin
        texCache[name] = t;
        return t;
    }

    /// <summary>Sabit çözünürlükte sprite (16 px = 1 birim gibi).</summary>
    public static Sprite Get(string name, float ppu = 16f, Vector2? pivot = null)
    {
        string key = name + "|" + ppu + "|" + (pivot.HasValue ? pivot.Value.ToString() : "c");
        Sprite s;
        if (spriteCache.TryGetValue(key, out s) && s != null) return s;
        var t = Tex(name);
        if (t == null) return null;
        s = Sprite.Create(t, new Rect(0, 0, t.width, t.height), pivot ?? new Vector2(0.5f, 0.5f), ppu);
        s.name = "ART_" + name;
        s.hideFlags = HideFlags.HideAndDontSave;
        spriteCache[key] = s;
        return s;
    }

    /// <summary>Çizimi istenen dünya boyutuna oturtan ölçekli sprite. fitMax: en büyük kenarı eşler.</summary>
    public static Sprite Fit(string name, Vector2 targetWorldSize, Vector2 pivot, bool useMax = true, float scale = 1f)
    {
        var t = Tex(name);
        if (t == null) return null;
        float ppu;
        if (useMax)
            ppu = Mathf.Max(t.width, t.height) / (Mathf.Max(targetWorldSize.x, targetWorldSize.y) * scale);
        else
            ppu = t.height / (targetWorldSize.y * scale);
        ppu = Mathf.Max(1f, Mathf.Round(ppu * 100f) / 100f);
        return Get(name, ppu, pivot);
    }
}
